(function(){
'use strict';
if(typeof DATA==='undefined' || typeof PUBLIC_DATA==='undefined') return;
const S=v=>(v==null?'':String(v));
const N=v=>S(v).toLowerCase().replace(/ё/g,'е').replace(/\s+/g,' ').trim();
const KIR='кириллина светлана алексеевна';
const ARD='ардашникова анна наумовна';
const REL='история религии изучаемой страны (региона)';
const PERS='24б/ф314-персидский/5';

function isReligion(r){return r && N(r.teacher)===KIR && N(r.discipline).includes(REL);}
function isArdPersLit(r){return r && N(r.teacher)===ARD && S(r.course).trim()==='3 бакалавриат' && N(r.discipline).includes('литература изучаемого региона') && N(r.group)===PERS;}

// Кириллина: обязательная религиоведческая лекция есть в актуальной заявке 2026/27,
// но Вт 13:00 теперь занят более поздней прямой правкой Г.Р. Аганиной —
// «Теория основного восточного языка» для арабистов И/П/Ф, включая политологов.
// Другие заявленные Кириллиной окна Вт/Пт также заняты её собственными занятиями
// либо подтверждённым ОВЯ этих групп. Поэтому не создаём новую накладку и не
// выдумываем исключительный день: сохраняем нагрузку и ауд.228, время — на согласование.
for(let i=DATA.length-1;i>=0;i--){ if(isReligion(DATA[i])) DATA.splice(i,1); }
DATA.push({
  group:'23Б/Ист-311_арабский/5; 23Б/Ист-314_пушту/5; 23Б/Ист-315_суахили/5; 23Б/Ист-316_хауса/5; 23Б/Пл-341_арабский/5; 23Б/Фл-321_арабский/5; 23Б/Фл-323_персидский/5; 23Б/Фл-324_турецкий/5',
  course:'3 бакалавриат',
  direction:'',
  day:'уточняется',
  time:'уточняется',
  discipline:'История религии изучаемой страны (региона) (Исламоведение) — лекции',
  extra:'2 акад. ч/нед.; совместное чтение; ведущая — С.А. Кириллина',
  teacher:'Кириллина Светлана Алексеевна',
  room_hint:'228',
  quality:'01.09.2026: восстановлено строго по актуальной заявке С.А. Кириллиной 2026/27. Заявлены Вт/Пт, 10:40/13:00/14:40/16:20; понедельник запрещён; обязательно оборудование. Прежний Вт 13:00 снят из-за более поздней прямой правки Г.Р. Аганиной: в этот слот у 24Б/И302, 24Б/П302 и 24Б/Ф302 стоит «Теория основного восточного языка», ауд.160. Остальные заявленные Вт/Пт окна конфликтуют с действующей сеткой групп или занятиями самой Кириллиной. Поэтому день/время не назначены произвольно. По прямому указанию 01.09.2026 ауд.228 за Кириллиной сохранена; после согласования нового общего слота проверить наличие проектора/компьютера.'
});

// Ардашникова: Чт 13:00 как бесконфликтный для преподавателя и группы слот сохраняем,
// но ауд.236 занята И.Б. Спектором. Переносим только аудиторию в 415.
DATA.forEach(r=>{
  if(!isArdPersLit(r)) return;
  if(r.day==='Чт' && r.time==='13:00'){
    r.room_hint='415';
    r.quality=(S(r.quality)?S(r.quality)+' | ':'')+'01.09.2026: ауд.236 снята — в Чт 13:00 она занята И.Б. Спектором. Время Чт 13:00 сохранено; литература не возвращается на Вт 13:00, где у 3 курса стоит западный/английский язык. Назначена ауд.415: обычная учебная аудитория из используемого персидским блоком пула; в актуальной проверяемой сетке точного занятия в 415 на Чт 13:00 не найдено.';
  }
});

const rows=typeof isServiceRow==='function'?DATA.filter(r=>!isServiceRow(r)):DATA.slice();
PUBLIC_DATA.splice(0,PUBLIC_DATA.length,...rows);
try{if(typeof buildGroupItems==='function')buildGroupItems();}catch(e){}
try{if(typeof buildBrowseList==='function')buildBrowseList();}catch(e){}
try{if(typeof showEmpty==='function')showEmpty();}catch(e){}
})();
